#include "stdlib/lapack/base/dlaset.h"
#include "stdlib/lapack/base/shared.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"
#include <stdint.h>

// Define a macro for computing the minimum value:
#define MIN(X, Y) (((X) < (Y)) ? (X) : (Y))

/**
* Sets the diagonal of a double-precision floating-point matrix `A` to a specified value.
*
* @param M        number of rows in matrix `A`
* @param N        number of columns in matrix `A`
* @param beta     value assigned to diagonal elements
* @param A        input matrix
* @param strideA1 stride of the first dimension of `A`
* @param strideA2 stride of the second dimension of `A`
* @param offsetA  starting index for `A`
*/
static void set_diagonal( const LAPACK_INT M, const LAPACK_INT N, const double beta, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA ) {
	LAPACK_INT sa;
	LAPACK_INT ia;
	LAPACK_INT i;
	LAPACK_INT n_diag;

	sa = strideA1 + strideA2;
	ia = offsetA;
	n_diag = MIN( M, N );
	for ( i = 0; i < n_diag; i++ ) {
		A[ ia ] = beta;
		ia += sa;
	}
}

/**
* Sets all elements of a double-precision floating-point matrix `A` to specified values.
*
* @param M        number of rows in matrix `A`
* @param N        number of columns in matrix `A`
* @param alpha    value assigned to off-diagonal elements
* @param beta     value assigned to diagonal elements
* @param A        input matrix
* @param strideA1 stride of the first dimension of `A`
* @param strideA2 stride of the second dimension of `A`
* @param offsetA  starting index for `A`
* @return         status code
*/
static LAPACK_INT stdlib_lapack_base_set_all( const LAPACK_INT M, const LAPACK_INT N, const double alpha, const double beta, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA ) {
	int64_t sa[ 2 ];
	LAPACK_INT da0;
	LAPACK_INT da1;
	LAPACK_INT S0;
	LAPACK_INT S1;
	LAPACK_INT ia;
	LAPACK_INT i0;
	LAPACK_INT i1;

	// Extract loop variables for purposes of loop interchange: dimensions and loop offset (pointer) increments...
	sa[ 0 ] = strideA1;
	sa[ 1 ] = strideA2;
	if ( stdlib_ndarray_is_row_major( 2, sa ) ) {
		// For row-major matrices, the last dimension has the fastest changing index...
		S0 = N;
		S1 = M;
		da0 = strideA2;                   // offset increment for innermost loop
		da1 = strideA1 - ( S0*strideA2 ); // offset increment for outermost loop
	} else { // column-major
		// For column-major matrices, the first dimension has the fastest changing index...
		S0 = M;
		S1 = N;
		da0 = strideA1;                   // offset increment for innermost loop
		da1 = strideA2 - ( S0*strideA1 ); // offset increment for outermost loop
	}

	// Set the pointer to the first indexed element...
	ia = offsetA;

	// Iterate over the matrix dimensions...
	for ( i1 = 0; i1 < S1; i1++ ) {
		for ( i0 = 0; i0 < S0; i0++ ) {
			A[ ia ] = alpha;
			ia += da0;
		}
		ia += da1;
	}
	set_diagonal( M, N, beta, A, strideA1, strideA2, offsetA );
	return 0;
}

/**
* Sets the upper triangular/trapezoidal part of a double-precision floating-point matrix `A` to specified values.
*
* @param M        number of rows in matrix `A`
* @param N        number of columns in matrix `A`
* @param alpha    value assigned to off-diagonal elements
* @param beta     value assigned to diagonal elements
* @param A        input matrix
* @param strideA1 stride of the first dimension of `A`
* @param strideA2 stride of the second dimension of `A`
* @param offsetA  starting index for `A`
* @return         status code
*/
static LAPACK_INT stdlib_lapack_base_set_upper( const LAPACK_INT M, const LAPACK_INT N, const double alpha, const double beta, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA ) {
	int64_t sa[ 2 ];
	LAPACK_INT ia;
	LAPACK_INT idx;
	LAPACK_INT i0;
	LAPACK_INT i1;

	ia = offsetA;
	sa[ 0 ] = strideA1;
	sa[ 1 ] = strideA2;
	if ( stdlib_ndarray_is_row_major( 2, sa ) ) {
		for ( i1 = 0; i1 < M; i1++ ) {
			idx = ia + ( i1*strideA2 );
			for ( i0 = i1; i0 < N; i0++ ) {
				A[ idx ] = alpha;
				idx += strideA2;
			}
			ia += strideA1;
		}
	} else {
		for ( i1 = 0; i1 < N; i1++ ) {
			idx = ia;
			for ( i0 = 0; i0 <= MIN( i1, M-1 ); i0++ ) {
				A[ idx ] = alpha;
				idx += strideA1;
			}
			ia += strideA2;
		}
	}
	set_diagonal( M, N, beta, A, strideA1, strideA2, offsetA );
	return 0;
}

/**
* Sets the lower triangular/trapezoidal part of a double-precision floating-point matrix `A` to specified values.
*
* @param M        number of rows in matrix `A`
* @param N        number of columns in matrix `A`
* @param alpha    value assigned to off-diagonal elements
* @param beta     value assigned to diagonal elements
* @param A        input matrix
* @param strideA1 stride of the first dimension of `A`
* @param strideA2 stride of the second dimension of `A`
* @param offsetA  starting index for `A`
* @return         status code
*/
static LAPACK_INT stdlib_lapack_base_set_lower( const LAPACK_INT M, const LAPACK_INT N, const double alpha, const double beta, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA ) {
	int64_t sa[ 2 ];
	LAPACK_INT ia;
	LAPACK_INT idx;
	LAPACK_INT i0;
	LAPACK_INT i1;

	ia = offsetA;
	sa[ 0 ] = strideA1;
	sa[ 1 ] = strideA2;
	if ( stdlib_ndarray_is_row_major( 2, sa ) ) {
		for ( i1 = 0; i1 < M; i1++ ) {
			idx = ia;
			for ( i0 = 0; i0 <= MIN( i1, N-1 ); i0++ ) {
				A[ idx ] = alpha;
				idx += strideA2;
			}
			ia += strideA1;
		}
	} else {
		for ( i1 = 0; i1 < N; i1++ ) {
			idx = ia + ( i1*strideA1 );
			for ( i0 = i1; i0 < M; i0++ ) {
				A[ idx ] = alpha;
				idx += strideA1;
			}
			ia += strideA2;
		}
	}
	set_diagonal( M, N, beta, A, strideA1, strideA2, offsetA );
	return 0;
}

/**
* Sets the off-diagonal elements and the diagonal elements of a double-precision floating-point matrix to specified values using alternative indexing semantics.
*
* @param uplo     specifies whether to set the upper or lower triangular/trapezoidal part of matrix `A`
* @param M        number of rows in matrix `A`
* @param N        number of columns in matrix `A`
* @param alpha    value assigned to off-diagonal elements
* @param beta     value assigned to diagonal elements
* @param A        input matrix
* @param strideA1 stride of the first dimension of `A`
* @param strideA2 stride of the second dimension of `A`
* @param offsetA  starting index for `A`
* @return         status code
*/
LAPACK_INT API_SUFFIX(c_dlaset_ndarray)( const int uplo, const LAPACK_INT M, const LAPACK_INT N, const double alpha, const double beta, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA ) {
	if ( uplo == LAPACK_UPPER_TRIANGLE ) {
		return stdlib_lapack_base_set_upper( M, N, alpha, beta, A, strideA1, strideA2, offsetA );
	}
	if ( uplo == LAPACK_LOWER_TRIANGLE ) {
		return stdlib_lapack_base_set_lower( M, N, alpha, beta, A, strideA1, strideA2, offsetA );
	}
	return stdlib_lapack_base_set_all( M, N, alpha, beta, A, strideA1, strideA2, offsetA );
}
